#!/usr/bin/env bash
set -u
set -o pipefail
REPO="${DEBUG_AI_HOST_REPO:-/home/admin1/projects/debug-ai}"
CONTAINER_REPO="/workspace/debug-ai"
QUEUE="$REPO/.debugai-input/server-command"
JQ_BIN="${DEBUG_AI_SERVER_COMMAND_JQ_BIN:-jq}"
GIT_BIN="${DEBUG_AI_SERVER_COMMAND_GIT_BIN:-git}"
TIMEOUT_BIN="${DEBUG_AI_SERVER_COMMAND_TIMEOUT_BIN:-timeout}"
DOCKER_BIN="${DEBUG_AI_SERVER_COMMAND_DOCKER_BIN:-docker}"
CURL_BIN="${DEBUG_AI_SERVER_COMMAND_CURL_BIN:-curl}"
DF_BIN="${DEBUG_AI_SERVER_COMMAND_DF_BIN:-df}"
GH_BIN="${DEBUG_AI_SERVER_COMMAND_GH_BIN:-gh}"
PYTHON_BIN="${DEBUG_AI_SERVER_COMMAND_PYTHON_BIN:-python3}"
err_code=""; request_id=""; command_id=""; action=""; request_repo=""; ACTIVE_REPO="$REPO"; command_exit_code=0; result_json="{}"
fail(){ err_code="${1:-ERROR}"; return 1; }
ensure_dir(){ mkdir -p -- "$1" && chmod 700 -- "$1"; }
atomic_json(){ local target="$1" json="$2" tmp; ensure_dir "$(dirname -- "$target")" || return 1; tmp="${target}.tmp-$$-$(date +%s%N)"; (umask 077; printf '%s\n' "$json" >"$tmp") || return 1; mv -f -- "$tmp" "$target"; }
run_timed(){ local seconds="$1"; shift; "$TIMEOUT_BIN" --signal=TERM --kill-after=2s "$seconds" "$@"; }
validate_request(){ local file="$1" now_ms expires root sub expected approval; "$JQ_BIN" -e '.schema=="debugai.server-command-request/v1" and (.id|type=="string" and test("^cmd_[0-9a-f]{24}$")) and ((.repo=="/workspace/debug-ai") or (.repo|test("^/workspace/debug-ai/\\.debugai-input/test-repos/[A-Za-z0-9._-]+$"))) and (.expires_at|type=="number") and (((.action=="read") and ((.command_id=="system.projects_inventory" or .command_id=="system.project_file_inspect" or .command_id=="project.pwd" or .command_id=="project.git_head" or .command_id=="project.git_status" or .command_id=="project.git_changed_paths" or .command_id=="project.git_recent_commits" or .command_id=="project.python_unittest" or .command_id=="service.debug_ai_state" or .command_id=="service.sandbox_state" or .command_id=="service.debug_ai_health" or .command_id=="service.debug_ai_logs" or .command_id=="system.disk_usage" or (.command_id=="asteria.baseline_probe_start" or .command_id=="asteria.baseline_probe_status" or .command_id=="canonical.devlog_activate_start" or .command_id=="canonical.devlog_activate_status") or .command_id=="github.auth_status" or .command_id=="github.repo_view" or .command_id=="github.pr_current" or .command_id=="github.actions_recent" or .command_id=="github.control_current" or .command_id=="github.gh_read")) and (if .command_id=="system.projects_inventory" then ((.arguments|type)=="array" and (.arguments|length)==1 and (.arguments[0]|type)=="string" and (.arguments[0]|test("^(0|[1-9][0-9]{0,3})$"))) elif .command_id=="system.project_file_inspect" then ((.arguments|type)=="array" and (.arguments|length)>=2 and (.arguments|length)<=4 and (.arguments[0]|type)=="string" and (.arguments[0]|test("^[A-Za-z0-9._-]{1,120}$")) and (.arguments[1]|type)=="string" and (.arguments[1]|test("^[A-Za-z0-9_./-]{1,180}$")) and (.arguments[1]!=".") and ((.arguments[1]|split("/")|index(".."))==null) and (if (.arguments|length)>=3 then (.arguments[2]|type)=="string" and (.arguments[2]|test("^(0|[1-9][0-9]{0,5})$")) and ((.arguments[2]|tonumber)<=999999) else true end) and (if (.arguments|length)==4 then (.arguments[3]|type)=="string" and (.arguments[3]|test("^(projects|worktrees|server-core)$")) and (if .arguments[3]=="server-core" then .arguments[0]=="server-core" else true end) else true end)) elif .command_id=="github.gh_read" then (.arguments|type=="array" and length>=1 and length<=16) elif .command_id=="service.debug_ai_logs" then ((.arguments|type)=="array" and (.arguments|length)==2 and ((.arguments[0]=="debug-ai") or (.arguments[0]=="sandbox-runner")) and ((.arguments[1]|type)=="string") and (.arguments[1]|test("^([1-9]|1[0-9]|20)$"))) elif .command_id=="project.python_unittest" then (.arguments|type=="array" and length==1 and (.arguments[0]|type=="string")) else true end))) or ((.action=="write") and .repo=="/workspace/debug-ai" and (((.command_id=="github.gh_write") and .human_approved==true and (.arguments|type=="array" and length>=2 and length<=24) and (.approval_class=="ROUTINE" or .approval_class=="MASTER")) or ((.command_id=="canonical.devlog_activate_start") and .human_approved==true and .master_approved==true and .approval_class=="MASTER" and (.arguments|type=="array" and length==0))))' "$file" >/dev/null || fail REQUEST_SCHEMA_OR_BOUNDARY_INVALID || return 1; request_id="$("$JQ_BIN" -r '.id' "$file")"; command_id="$("$JQ_BIN" -r '.command_id' "$file")"; action="$("$JQ_BIN" -r '.action' "$file")"; request_repo="$("$JQ_BIN" -r '.repo' "$file")"; ACTIVE_REPO="$REPO"; if [ "$request_repo" != "$CONTAINER_REPO" ]; then rel="${request_repo#"$CONTAINER_REPO"/}"; ACTIVE_REPO="$REPO/$rel"; [ -d "$ACTIVE_REPO/.git" ] || fail SERVER_COMMAND_TARGET_REPO_INVALID || return 1; real_active="$(cd "$ACTIVE_REPO" && pwd -P)" || fail SERVER_COMMAND_TARGET_REPO_INVALID || return 1; real_root="$(cd "$REPO/.debugai-input/test-repos" && pwd -P)" || fail SERVER_COMMAND_TEST_ROOT_INVALID || return 1; case "$real_active" in "$real_root"/*) ACTIVE_REPO="$real_active";; *) fail SERVER_COMMAND_TARGET_REPO_ESCAPE; return 1;; esac; fi; if [ "$command_id" = "github.gh_read" ]; then "$JQ_BIN" -e '(.arguments[0] as $r | ["api","repo","pr","issue","run","workflow","release","search","auth","project"] | index($r) != null) and ([.arguments[1:][]? | select(.=="create" or .=="edit" or .=="delete" or .=="merge" or .=="close" or .=="reopen" or .=="comment" or .=="review" or .=="ready" or .=="lock" or .=="unlock" or .=="rerun" or .=="cancel" or .=="watch" or .=="enable" or .=="disable" or .=="run")] | length==0) and (if .arguments[0]=="api" then ([.arguments[1:][]? | select(.=="-f" or .=="-F" or .=="--field" or .=="--raw-field" or .=="--input" or startswith("--field=") or startswith("--raw-field=") or startswith("--input="))] | length==0) and (.arguments[1]!="graphql") and ([range(1;(.arguments|length)) as $i | select((.arguments[$i]=="--method" or .arguments[$i]=="-X") and ((.arguments[$i+1]//"")|ascii_upcase)!="GET")] | length==0) and ([.arguments[1:][]? | select(startswith("--method=") and ((split("=")[1]//"")|ascii_upcase)!="GET")] | length==0) else true end)' "$file" >/dev/null || fail GITHUB_GH_READ_BOUNDARY_INVALID || return 1; fi; if [ "$command_id" = "github.gh_write" ]; then root="$("$JQ_BIN" -r '.arguments[0]' "$file")"; sub="$("$JQ_BIN" -r '.arguments[1]' "$file")"; approval="$("$JQ_BIN" -r '.approval_class' "$file")"; expected=""; case "$root:$sub" in issue:create|issue:edit|issue:close|issue:reopen|issue:comment|issue:lock|issue:unlock|issue:pin|issue:unpin|issue:transfer|pr:create|pr:edit|pr:close|pr:reopen|pr:comment|pr:review|pr:ready|project:create|project:edit|project:copy|project:item-add|project:item-archive|project:item-create|project:item-delete|project:item-edit|project:link|project:unlink|label:create|label:edit|label:delete|label:clone) expected="ROUTINE";; pr:merge|repo:create|repo:edit|repo:archive|repo:delete|repo:rename|repo:fork|release:create|release:edit|release:delete|release:upload|run:rerun|run:cancel|run:delete|workflow:run|workflow:enable|workflow:disable|api:*) expected="MASTER";; *) fail GITHUB_GH_WRITE_OPERATION_NOT_ALLOWED; return 1;; esac; [ "$approval" = "$expected" ] || { fail GITHUB_GH_WRITE_APPROVAL_CLASS_MISMATCH; return 1; }; if [ "$expected" = "MASTER" ]; then "$JQ_BIN" -e '.master_approved==true' "$file" >/dev/null || fail GITHUB_GH_WRITE_MASTER_APPROVAL_REQUIRED || return 1; fi; fi; expires="$("$JQ_BIN" -r '.expires_at|floor' "$file")"; now_ms="$(date +%s%3N)"; [ "$now_ms" -le "$expires" ] || fail REQUEST_EXPIRED || return 1; }
run_read_command(){ local output test_rel test_file test_real; command_exit_code=0; case "$command_id" in project.pwd) output="$(cd "$ACTIVE_REPO" && pwd -P)" || { fail COMMAND_EXEC_FAILED; return 1; };; project.git_head) output="$(cd "$ACTIVE_REPO" && run_timed 5s "$GIT_BIN" rev-parse HEAD)" || { fail COMMAND_EXEC_FAILED; return 1; };;
project.git_status) branch="$(cd "$ACTIVE_REPO" && run_timed 5s "$GIT_BIN" branch --show-current)" || { fail COMMAND_EXEC_FAILED; return 1; }; dirty="$(cd "$ACTIVE_REPO" && { "$GIT_BIN" diff --name-only; "$GIT_BIN" diff --cached --name-only; "$GIT_BIN" ls-files --others --exclude-standard; } | sed '/^$/d;/^\.debugai-input\//d' | LC_ALL=C sort -u | wc -l | tr -d '[:space:]')" || { fail COMMAND_EXEC_FAILED; return 1; }; output="branch=$branch|dirty_count=$dirty";;
project.git_changed_paths) output="$(cd "$ACTIVE_REPO" && { "$GIT_BIN" diff --name-only; "$GIT_BIN" diff --cached --name-only; "$GIT_BIN" ls-files --others --exclude-standard; } | sed '/^$/d;/^\.debugai-input\//d' | LC_ALL=C sort -u | head -n 40)" || { fail COMMAND_EXEC_FAILED; return 1; };;
project.git_recent_commits) output="$(cd "$ACTIVE_REPO" && run_timed 5s "$GIT_BIN" log -n 8 --format='%h %s')" || { fail COMMAND_EXEC_FAILED; return 1; };;
project.python_unittest) command -v "$PYTHON_BIN" >/dev/null 2>&1 || { fail PYTHON_UNITTEST_PYTHON_UNAVAILABLE; return 1; }; [ "$ACTIVE_REPO" != "$REPO" ] || { fail PYTHON_UNITTEST_TEST_REPO_REQUIRED; return 1; }; test_rel="$("$JQ_BIN" -r '.arguments[0]' "$processing")"; [[ "$test_rel" =~ ^[A-Za-z0-9_./-]+\.py$ ]] && [[ "$test_rel" != /* ]] && [[ "$test_rel" != *".."* ]] || { fail PYTHON_UNITTEST_PATH_INVALID; return 1; }; test_file="$ACTIVE_REPO/$test_rel"; [ -f "$test_file" ] || { fail PYTHON_UNITTEST_FILE_NOT_FOUND; return 1; }; test_real="$(cd "$(dirname -- "$test_file")" && pwd -P)/$(basename -- "$test_file")"; case "$test_real" in "$ACTIVE_REPO"/*) ;; *) fail PYTHON_UNITTEST_PATH_ESCAPE; return 1;; esac; output="$(cd "$ACTIVE_REPO" && run_timed 30s "$PYTHON_BIN" "$test_real" 2>&1)"; command_exit_code=$?; [ "$command_exit_code" -ne 124 ] || { fail PYTHON_UNITTEST_TIMEOUT; return 1; };;
service.debug_ai_state) cid="$(cd "$REPO" && "$DOCKER_BIN" compose ps -q debug-ai 2>/dev/null | head -n1)"; [ -n "$cid" ] || { fail COMMAND_EXEC_FAILED; return 1; }; output="$("$DOCKER_BIN" inspect -f '{{.State.Status}}|{{if .State.Health}}{{.State.Health.Status}}{{else}}NONE{{end}}' "$cid" 2>/dev/null)" || { fail COMMAND_EXEC_FAILED; return 1; };;
service.sandbox_state) cid="$(cd "$REPO" && "$DOCKER_BIN" compose ps -q sandbox-runner 2>/dev/null | head -n1)"; [ -n "$cid" ] || { fail COMMAND_EXEC_FAILED; return 1; }; output="$("$DOCKER_BIN" inspect -f '{{.State.Status}}|{{if .State.Health}}{{.State.Health.Status}}{{else}}NONE{{end}}' "$cid" 2>/dev/null)" || { fail COMMAND_EXEC_FAILED; return 1; };;
service.debug_ai_logs) service_name="$("$JQ_BIN" -r '.arguments[0]' "$processing")"; tail_lines="$("$JQ_BIN" -r '.arguments[1]' "$processing")"; case "$service_name" in debug-ai|sandbox-runner) ;; *) fail SERVER_LOG_SERVICE_DENIED; return 1;; esac; cid="$(cd "$REPO" && "$DOCKER_BIN" compose ps -q "$service_name" 2>/dev/null | head -n1)"; [ -n "$cid" ] || { fail SERVER_LOG_CONTAINER_MISSING; return 1; }; output="$(run_timed 10s "$DOCKER_BIN" logs --tail "$tail_lines" --timestamps "$cid" 2>&1 | awk '{content=tolower($0);if(content ~ /token|secret|bearer|password|credential|authorization|cookie|private.key|api.key/){print "[REDACTED_SENSITIVE_LINE]"}else{print $0}}' | tail -c 3400)" || { fail SERVER_LOG_READ_FAILED; return 1; };; service.debug_ai_health) code="$("$CURL_BIN" -sS -o /dev/null -w '%{http_code}' --connect-timeout 2 --max-time 5 http://127.0.0.1:8787/health)" || { fail COMMAND_EXEC_FAILED; return 1; }; output="http_status=$code";;
system.projects_inventory) page="$("$JQ_BIN" -r '.arguments[0]' "$processing")"; [ -f "$REPO/scripts/host-workspace-inventory.py" ] || { fail PROJECT_INVENTORY_HELPER_NOT_FOUND; return 1; }; output="$(run_timed 20s "$PYTHON_BIN" "$REPO/scripts/host-workspace-inventory.py" "$page")" || { fail PROJECT_INVENTORY_EXEC_FAILED; return 1; };;
system.project_file_inspect) entry_name="$("$JQ_BIN" -r '.arguments[0]' "$processing")"; inspect_rel="$("$JQ_BIN" -r '.arguments[1]' "$processing")"; inspect_offset="$("$JQ_BIN" -r '.arguments[2] // "0"' "$processing")"; inspect_root_key="$("$JQ_BIN" -r '.arguments[3] // empty' "$processing")"; [ -f "$REPO/scripts/host-workspace-file-inspect.py" ] || { fail PROJECT_FILE_INSPECT_HELPER_NOT_FOUND; return 1; }; [ -f "$REPO/operations/host-admitted-workspace-entries.json" ] || { fail PROJECT_FILE_INSPECT_REGISTRY_NOT_FOUND; return 1; }; inspect_cmd=("$PYTHON_BIN" "$REPO/scripts/host-workspace-file-inspect.py" "$entry_name" "$inspect_rel" "$inspect_offset"); [ -n "$inspect_root_key" ] && inspect_cmd+=("$inspect_root_key"); output="$(run_timed 20s "${inspect_cmd[@]}")" || { fail PROJECT_FILE_INSPECT_EXEC_FAILED; return 1; };;
system.disk_usage) output="$("$DF_BIN" -Pk "$REPO" | awk 'NR==2 {print "blocks_kb="$2"|used_kb="$3"|available_kb="$4"|used_percent="$5}')" || { fail COMMAND_EXEC_FAILED; return 1; };;
asteria.baseline_probe_start) PROBE_RESULT="$REPO/.debugai-input/asteria-baseline-probe/result.json"; PROBE_SCRIPT="$REPO/scripts/host-asteria-baseline-probe.sh"; [ -f "$PROBE_SCRIPT" ] || { fail ASTERIA_PROBE_SCRIPT_NOT_FOUND; return 1; }; if systemctl --user is-active --quiet debugai-asteria-baseline-probe.service 2>/dev/null; then fail ASTERIA_PROBE_ALREADY_RUNNING; return 1; fi; ensure_dir "$(dirname -- "$PROBE_RESULT")" || { fail ASTERIA_PROBE_RESULT_DIR_FAILED; return 1; }; "$JQ_BIN" -n --argjson started "$(date +%s%3N)" '{schema:"debugai.asteria-baseline-probe/v1",state:"RUNNING",started_at:$started}' >"$PROBE_RESULT" || { fail ASTERIA_PROBE_RESULT_INIT_FAILED; return 1; }; systemd-run --user --unit=debugai-asteria-baseline-probe --collect --property=RuntimeMaxSec=420 /usr/bin/env bash "$PROBE_SCRIPT" >/dev/null 2>&1 || { fail ASTERIA_PROBE_START_FAILED; return 1; }; output="state=STARTED|result_file=.debugai-input/asteria-baseline-probe/result.json";;
asteria.baseline_probe_status) PROBE_RESULT="$REPO/.debugai-input/asteria-baseline-probe/result.json"; [ -f "$PROBE_RESULT" ] || { fail ASTERIA_PROBE_RESULT_NOT_FOUND; return 1; }; output="$(cat "$PROBE_RESULT" 2>/dev/null)" || { fail ASTERIA_PROBE_RESULT_READ_FAILED; return 1; };;
canonical.devlog_activate_start) DEVLOG_RESULT="$REPO/.debugai-input/canonical-devlog-activation/result.json"; DEVLOG_SCRIPT="$REPO/scripts/host-canonical-devlog-activate.sh"; [ -f "$DEVLOG_SCRIPT" ] || { fail CANONICAL_DEVLOG_SCRIPT_NOT_FOUND; return 1; }; if systemctl --user is-active --quiet debugai-canonical-devlog-activate.service 2>/dev/null; then fail CANONICAL_DEVLOG_ALREADY_RUNNING; return 1; fi; ensure_dir "$(dirname -- "$DEVLOG_RESULT")" || { fail CANONICAL_DEVLOG_RESULT_DIR_FAILED; return 1; }; "$JQ_BIN" -n --argjson started "$(date +%s%3N)" '{schema:"debugai.canonical-devlog-activation/v1",state:"RUNNING",started_at:$started}' >"$DEVLOG_RESULT" || { fail CANONICAL_DEVLOG_RESULT_INIT_FAILED; return 1; }; systemd-run --user --unit=debugai-canonical-devlog-activate --collect --property=RuntimeMaxSec=1800 /usr/bin/env bash "$DEVLOG_SCRIPT" >/dev/null 2>&1 || { fail CANONICAL_DEVLOG_START_FAILED; return 1; }; output="state=STARTED|result_file=.debugai-input/canonical-devlog-activation/result.json";;
canonical.devlog_activate_status) DEVLOG_RESULT="$REPO/.debugai-input/canonical-devlog-activation/result.json"; [ -f "$DEVLOG_RESULT" ] || { fail CANONICAL_DEVLOG_RESULT_NOT_FOUND; return 1; }; output="$(cat "$DEVLOG_RESULT" 2>/dev/null)" || { fail CANONICAL_DEVLOG_RESULT_READ_FAILED; return 1; };;
github.auth_status) command -v "$GH_BIN" >/dev/null 2>&1 || { fail GH_CLI_UNAVAILABLE; return 1; }; output="$("$GH_BIN" auth status -h github.com 2>&1 | sed -E 's/(Token: ).*/\1[REDACTED]/; s/(oauth_token: ).*/\1[REDACTED]/' | head -n 12)" || { fail GH_AUTH_UNAVAILABLE; return 1; };;
github.repo_view) command -v "$GH_BIN" >/dev/null 2>&1 || { fail GH_CLI_UNAVAILABLE; return 1; }; output="$("$GH_BIN" repo view seigo-gace/debug-ai --json nameWithOwner,defaultBranchRef,isPrivate,url 2>/dev/null)" || { fail COMMAND_EXEC_FAILED; return 1; };;
github.pr_current) command -v "$GH_BIN" >/dev/null 2>&1 || { fail GH_CLI_UNAVAILABLE; return 1; }; branch="$(cd "$REPO" && "$GIT_BIN" branch --show-current)" || { fail COMMAND_EXEC_FAILED; return 1; }; output="$("$GH_BIN" pr view "$branch" --repo seigo-gace/debug-ai --json number,state,isDraft,mergeable,headRefName,headRefOid,baseRefName,url 2>/dev/null)" || { fail COMMAND_EXEC_FAILED; return 1; };;
github.actions_recent) command -v "$GH_BIN" >/dev/null 2>&1 || { fail GH_CLI_UNAVAILABLE; return 1; }; branch="$(cd "$REPO" && "$GIT_BIN" branch --show-current)" || { fail COMMAND_EXEC_FAILED; return 1; }; output="$("$GH_BIN" run list --repo seigo-gace/debug-ai --branch "$branch" --limit 8 --json databaseId,name,status,conclusion,headSha,event,url 2>/dev/null)" || { fail COMMAND_EXEC_FAILED; return 1; };;
github.control_current) command -v "$GH_BIN" >/dev/null 2>&1 || { fail GH_CLI_UNAVAILABLE; return 1; }; output="$("$GH_BIN" issue view 41 --repo seigo-gace/debug-ai --json number,title,state,updatedAt,url,body 2>/dev/null | "$JQ_BIN" -c '{number,title,state,updatedAt,url,body:(.body|tostring|.[0:2500])}')" || { fail COMMAND_EXEC_FAILED; return 1; };;
github.gh_read) command -v "$GH_BIN" >/dev/null 2>&1 || { fail GH_CLI_UNAVAILABLE; return 1; }; mapfile -t gh_args < <("$JQ_BIN" -r '.arguments[]' "$processing"); [ "${#gh_args[@]}" -ge 1 ] || { fail REQUEST_SCHEMA_OR_BOUNDARY_INVALID; return 1; }; output="$(cd "$ACTIVE_REPO" && run_timed 10s "$GH_BIN" "${gh_args[@]}" 2>&1)" || { fail COMMAND_EXEC_FAILED; return 1; };;
github.gh_write) command -v "$GH_BIN" >/dev/null 2>&1 || { fail GH_CLI_UNAVAILABLE; return 1; }; mapfile -t gh_args < <("$JQ_BIN" -r '.arguments[]' "$processing"); [ "${#gh_args[@]}" -ge 2 ] || { fail REQUEST_SCHEMA_OR_BOUNDARY_INVALID; return 1; }; output="$(cd "$ACTIVE_REPO" && run_timed 20s "$GH_BIN" "${gh_args[@]}" 2>&1)" || { fail COMMAND_EXEC_FAILED; return 1; };;
*) fail COMMAND_NOT_ALLOWED; return 1;; esac; [ "${#output}" -le 4096 ] || { fail COMMAND_OUTPUT_TOO_LARGE; return 1; }; if [ "$action" = "read" ]; then result_json="$("$JQ_BIN" -n --arg command_id "$command_id" --arg stdout "$output" --argjson exit_code "$command_exit_code" '{command_id:$command_id,stdout:$stdout,exit_code:$exit_code,read_only:true}')"; else result_json="$("$JQ_BIN" -n --arg command_id "$command_id" --arg stdout "$output" '{command_id:$command_id,stdout:$stdout,exit_code:0,read_only:false}')"; fi; }
process_file(){ local source="$1" processing done_dir failed_dir started finished status id_for_status mirror_id running_status; started="$(date +%s%3N)"; processing="$QUEUE/processing/$(basename -- "$source")"; done_dir="$QUEUE/done"; failed_dir="$QUEUE/failed"; ensure_dir "$QUEUE/processing" || return 1; ensure_dir "$done_dir" || return 1; ensure_dir "$failed_dir" || return 1; mirror_id="$(basename -- "$source" .json)"; [[ "$mirror_id" =~ ^cmd_[0-9a-f]{24}$ ]] || mirror_id=""; mv -- "$source" "$processing" || return 1; if [ -n "$mirror_id" ]; then running_status="$("$JQ_BIN" -n --arg id "$mirror_id" --argjson started "$started" '{schema:"debugai.server-command-status/v1",id:$id,started_at:$started,state:"RUNNING"}')"; atomic_json "$QUEUE/readback_${mirror_id}.json" "$running_status" || return 1; fi; request_id="$mirror_id"; command_id=""; action=""; request_repo=""; ACTIVE_REPO="$REPO"; command_exit_code=0; err_code=""; result_json="{}"; validate_request "$processing" && run_read_command || true; finished="$(date +%s%3N)"; id_for_status="$request_id"; [[ "$id_for_status" =~ ^cmd_[0-9a-f]{24}$ ]] || id_for_status="invalid_${finished}"; if [ -z "$err_code" ]; then status="$("$JQ_BIN" -n --arg id "$request_id" --arg command_id "$command_id" --argjson started "$started" --argjson finished "$finished" --argjson result "$result_json" '{schema:"debugai.server-command-status/v1",id:$id,command_id:$command_id,started_at:$started,state:"PASS",finished_at:$finished,result:$result}')"; atomic_json "$QUEUE/status/${id_for_status}.json" "$status" || return 1; [ -z "$mirror_id" ] || atomic_json "$QUEUE/readback_${mirror_id}.json" "$status" || return 1; mv -- "$processing" "$done_dir/$(basename -- "$processing")"; else status="$("$JQ_BIN" -n --arg id "$id_for_status" --arg command_id "$command_id" --argjson started "$started" --argjson finished "$finished" --arg error "${err_code:0:120}" '{schema:"debugai.server-command-status/v1",id:$id,command_id:$command_id,started_at:$started,state:"FAIL",finished_at:$finished,error:$error}')"; atomic_json "$QUEUE/status/${id_for_status}.json" "$status" || return 1; if [ -n "$mirror_id" ]; then mirror_status="$("$JQ_BIN" -n --arg id "$mirror_id" --arg command_id "$command_id" --argjson started "$started" --argjson finished "$finished" --arg error "${err_code:0:120}" '{schema:"debugai.server-command-status/v1",id:$id,command_id:$command_id,started_at:$started,state:"FAIL",finished_at:$finished,error:$error}')"; atomic_json "$QUEUE/readback_${mirror_id}.json" "$mirror_status" || return 1; fi; mv -- "$processing" "$failed_dir/$(basename -- "$processing")"; fi; }
main(){ local lock_dir request_dir name count=0 cmd; for cmd in "$JQ_BIN" "$GIT_BIN" "$TIMEOUT_BIN" "$DOCKER_BIN" "$CURL_BIN" "$DF_BIN"; do command -v "$cmd" >/dev/null 2>&1 || { printf 'debugai-server-command-runner:DEPENDENCY_MISSING:%s\n' "$cmd" >&2; return 1; }; done; [ -d "$REPO/.git" ] || { printf 'debugai-server-command-runner:REPO_INVALID\n' >&2; return 1; }; request_dir="$QUEUE/requests"; ensure_dir "$request_dir" || return 1; ensure_dir "$QUEUE/status" || return 1; lock_dir="$QUEUE/.runner.lock"; if ! mkdir -- "$lock_dir" 2>/dev/null; then return 0; fi; trap 'rmdir -- "$lock_dir" 2>/dev/null || true' EXIT INT TERM; while IFS= read -r name; do [ -n "$name" ] || continue; process_file "$request_dir/$name" || return 1; count=$((count+1)); [ "$count" -ge 8 ] && break; done < <(find "$request_dir" -maxdepth 1 -type f -name 'cmd_*.json' -printf '%f\n' | LC_ALL=C sort); trap - EXIT INT TERM; rmdir -- "$lock_dir" 2>/dev/null || true; }
main "$@"
